// Remove Duplicates from Sorted Array in-place
var array = AnimatedArray<Int>()
array.append(1)
array.append(1)
array.append(2)
array.append(2)
array.append(3)

func removeDuplicates(arr: inout AnimatedArray<Int>) {
    var i = 0
    while i < arr.count - 1 {
        if let val1 = arr.at(i), let val2 = arr.at(i + 1), val1 == val2 {
            arr.remove(at: i + 1)
        } else {
            i += 1
        }
    }
}

removeDuplicates(arr: &array)
